const {setup:base,pay,state,root}=require('../qa-cycle55-story/setup.cjs');
const ids=['story_family_key','main_recovery_story_family_key','postman_again'];
function setup(){const h=base();h.run(`qaResult=(e,c,out)=>{const authored=out.frozenTextOnly?null:typeof out.turns==='function'?out.turns(S):out.turns;return Array.isArray(authored)&&authored.length?authored:buildStoryTurns(prose(out.text),e,{knownSpeaker:!!S.pendingPresentation?.knownSpeaker,speakers:out.speakers,frozenTextOnly:!!out.frozenTextOnly,turnSpeakers:out.frozenTextOnly?[]:D.finaleSpeakers(e.id,e.choices.indexOf(c),S)||out.turnSpeakers});};`);return h;}
function fresh(id,min=600,capture=true){const h=setup();h.run(`S.pendingPresentation=null;S.at=${JSON.stringify(id.startsWith('main_recovery')?'suwon':'muju')};S.driving=null;S.day=9;S.min=${min};S.food=12;S.water=20;S.fuel=40;S.scrap=30;S.fatigue=35;S.hunger=0;S.van=90;S.party=[];S.flags.postman_met=true;globalThis.e=event(${JSON.stringify(id)});G.beginPresentation(e);globalThis.entry=qaEntry(e),info=qaInfo(e,'event',[],entry);`);if(capture)h.run("G.capturePresentationView({eventId:e.id,phase:'event',turns:entry,...info,index:0})");return h;}
module.exports={setup,fresh,pay,state,root,ids};
